pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(address vader, address usdv, address vault) internal {
        vm.assume(true);
        try c.init(vader, usdv, vault) {} catch { return; }
        assertTrue(c.coolOffPeriod() == 1);
    }

    function testFuzz_run(address vader, address usdv, address vault) public {
        vm.assume(vader.code.length == 0 && uint160(vader) > 0xffff && vader != address(this) && vader != address(c) && vader != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && vader != 0x000000000000000000636F6e736F6c652e6c6f67 && vader != 0x4e59b44847b379578588920cA78FbF26c0B4956C && vader != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(usdv.code.length == 0 && uint160(usdv) > 0xffff && usdv != address(this) && usdv != address(c) && usdv != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && usdv != 0x000000000000000000636F6e736F6c652e6c6f67 && usdv != 0x4e59b44847b379578588920cA78FbF26c0B4956C && usdv != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(vault.code.length == 0 && uint160(vault) > 0xffff && vault != address(this) && vault != address(c) && vault != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && vault != 0x000000000000000000636F6e736F6c652e6c6f67 && vault != 0x4e59b44847b379578588920cA78FbF26c0B4956C && vault != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(vader, usdv, vault);
    }

    receive() external payable {}
}
